/// When the event loop may queue a full-screen `Renderer::draw` (Clear+repaint).
///
/// GNU mc is idle-stable: it does not full-repaint unless input, C-l, or a timer
/// that actually changed a cell (progress bars, find results, PTY output, Esc
/// prefix expiry). The listing cursor does not blink the whole screen.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct PaintNeed {
    /// First frame, or a key/mouse/resize was handled since the last paint.
    input_or_first_frame: bool,
    /// GNU C-l (`needs_full_clear`).
    force_clear: bool,
    /// File-op progress, find-result drain, PTY output, skin change, resize.
    timed_ui_changed: bool,
}

fn should_full_paint(need: PaintNeed) -> bool {
    need.input_or_first_frame || need.force_clear || need.timed_ui_changed
}

/// Event-loop tick: queue `Renderer::draw` (Clear+repaint) only when `need` is set.
fn tick_emits_full_redraw(need: PaintNeed) -> bool {
    should_full_paint(need)
}

fn compose_paint_need(
    input_or_first_frame: bool,
    force_clear: bool,
    size_changed: bool,
    timed_cells_changed: bool,
) -> PaintNeed {
    PaintNeed {
        input_or_first_frame,
        force_clear,
        timed_ui_changed: size_changed || timed_cells_changed,
    }
}

/// Mouse kinds that GNU mc treats as input. Motion / release / drag do not
/// change a cell by themselves and must not force Clear+repaint.
fn mouse_kind_requests_paint(kind: MouseEventKind) -> bool {
    matches!(
        kind,
        MouseEventKind::Down(_)
            | MouseEventKind::ScrollUp
            | MouseEventKind::ScrollDown
            | MouseEventKind::ScrollLeft
            | MouseEventKind::ScrollRight
    )
}

/// Progress-dialog cells for the current tick. `None` when not in FileOpProgress.
fn file_op_progress_view_for_paint(
    app: &App,
    cols: u16,
) -> Option<rmc_core::fileop::FileOpProgressView> {
    match &app.ui_mode {
        UiMode::FileOpProgress { state, .. } => {
            let w = (cols as usize).min(74);
            let bar_width = w.saturating_sub(6).max(16);
            Some(state.view(bar_width, app.panel_opts.kilobyte_si))
        }
        _ => None,
    }
}

// Keep the current viewer's effective bytes alive across renders and filtering.
// Stores the original display path and the current ViewData (may reference a temp file).
pub(crate) struct ViewerState {
    pub display_path: std::path::PathBuf,
    pub view: rmc_view::ViewData,
}

use once_cell::sync::Lazy;
use std::sync::Mutex;
pub(crate) static VIEWER_STATE: Lazy<Mutex<Option<ViewerState>>> = Lazy::new(|| Mutex::new(None));
/// Parked viewer bytes for screens that are not currently displayed.
static VIEWER_CACHE: Lazy<Mutex<HashMap<PathBuf, ViewerState>>> =
    Lazy::new(|| Mutex::new(HashMap::new()));

// Persistent PTY-backed subshell session for C-o console.
// Lives in the UI crate to avoid widening App's trait bounds or Debug/Clone surface.
pub(crate) static SUBSHELL_PTY: Lazy<Mutex<Option<rmc_core::subshell::PtySession>>> =
    Lazy::new(|| Mutex::new(None));

fn replace_opts(dlg: &EditorReplaceDialog) -> rmc_edit::SearchOptions {
    rmc_edit::SearchOptions {
        case_sensitive: dlg.case_sensitive,
        backwards: dlg.backwards,
        whole_words: dlg.whole_words,
        regexp: dlg.regular_expression,
    }
}

/// Replace the next match from the cursor, honoring dialog options. Empty
/// needle is a no-op (does not wipe the buffer). On success the cursor
/// advances past the replacement so another Replace finds the following match
/// (backwards: cursor stays at the replacement so the next search continues
/// toward the start). Dialog stays open.
fn editor_replace_next(
    buf: &mut rmc_edit::EditorBuffer,
    dlg: &mut EditorReplaceDialog,
) -> Option<String> {
    if dlg.search.is_empty() {
        return None;
    }
    match buf.replace_next_with_options(
        dlg.search.as_bytes(),
        dlg.replacement.as_bytes(),
        replace_opts(dlg),
        true,
    ) {
        Some(_) => {
            dlg.on_match = false;
            Some("Replaced".into())
        }
        None => {
            dlg.on_match = false;
            Some("Not found".into())
        }
    }
}

/// Replace remaining matches from the cursor. Empty needle is a no-op and
/// returns None so the caller can leave the dialog open without changing the
/// buffer.
fn editor_replace_all(
    buf: &mut rmc_edit::EditorBuffer,
    dlg: &EditorReplaceDialog,
) -> Option<usize> {
    if dlg.search.is_empty() {
        return None;
    }
    Some(buf.replace_all_with_options(
        dlg.search.as_bytes(),
        dlg.replacement.as_bytes(),
        replace_opts(dlg),
    ))
}

/// Skip this match: move to the next match without replacing. Empty needle is
/// a no-op. If none, status is `Not found` and the dialog stays open.
fn editor_replace_skip(
    buf: &mut rmc_edit::EditorBuffer,
    dlg: &mut EditorReplaceDialog,
) -> Option<String> {
    if dlg.search.is_empty() {
        return None;
    }
    let found = if dlg.on_match {
        let _ = buf.search_with_options(
            dlg.search.as_bytes(),
            dlg.case_sensitive,
            dlg.backwards,
            dlg.whole_words,
            dlg.regular_expression,
            false,
        );
        buf.search_next_opts(false)
    } else {
        buf.search_with_options(
            dlg.search.as_bytes(),
            dlg.case_sensitive,
            dlg.backwards,
            dlg.whole_words,
            dlg.regular_expression,
            false,
        )
    };
    match found {
        Some(_) => {
            dlg.on_match = true;
            Some("Found".into())
        }
        None => {
            dlg.on_match = false;
            Some("Not found".into())
        }
    }
}

/// Pipe selection (or whole buffer) through `cmd`. Empty command is a no-op
/// (does not wipe the file). On failure `pipe_selection` leaves the buffer
/// unchanged and the error text is returned for `status_msg`.
fn editor_pipe_run(buf: &mut rmc_edit::EditorBuffer, cmd: &str) -> Option<String> {
    let cmd = cmd.trim();
    if cmd.is_empty() {
        return None;
    }
    match buf.pipe_selection(cmd) {
        Ok(()) => None,
        Err(e) => Some(format!("{e}")),
    }
}

/// Run a Search-dialog query. Empty needle is a no-op (no cursor change).
/// On success/failure returns the GNU status line (`Found` / `Not found`).
fn editor_search_run(buf: &mut rmc_edit::EditorBuffer, dlg: &EditorSearchDialog) -> Option<String> {
    if dlg.search.is_empty() {
        return None;
    }
    match buf.search_with_options(
        dlg.search.as_bytes(),
        dlg.case_sensitive,
        dlg.backwards,
        dlg.whole_words,
        dlg.regular_expression,
        true,
    ) {
        Some(_) => Some("Found".into()),
        None => Some("Not found".into()),
    }
}

fn viewer_search_kind(t: ViewerSearchType) -> rmc_view::SearchKind {
    match t {
        ViewerSearchType::Normal => rmc_view::SearchKind::Normal,
        ViewerSearchType::RegularExpression => rmc_view::SearchKind::RegularExpression,
        ViewerSearchType::Hexadecimal => rmc_view::SearchKind::Hexadecimal,
        ViewerSearchType::WildcardSearch => rmc_view::SearchKind::WildcardSearch,
    }
}

fn viewer_search_opts(
    case_sensitive: bool,
    backwards: bool,
    whole_words: bool,
    search_type: ViewerSearchType,
    all_charsets: bool,
) -> rmc_view::SearchOptions {
    rmc_view::SearchOptions {
        case_sensitive,
        backwards,
        whole_words,
        kind: viewer_search_kind(search_type),
        all_charsets,
    }
}

/// Run a viewer Search-dialog query. Empty needle is a no-op (no offset change).
/// On success/failure returns the GNU status line (`Found` / `Not found`),
/// or the GNU hex-pattern error text.
#[allow(clippy::too_many_arguments)]
fn viewer_search_run(
    path: &std::path::Path,
    offset: &mut u64,
    search: &mut Option<String>,
    case_sensitive: &mut bool,
    backwards: &mut bool,
    whole_words: &mut bool,
    search_type: &mut ViewerSearchType,
    all_charsets: &mut bool,
    dlg: &ViewerSearchDialog,
) -> anyhow::Result<Option<String>> {
    if dlg.search.is_empty() {
        return Ok(None);
    }
    *search = Some(dlg.search.clone());
    *case_sensitive = dlg.case_sensitive;
    *backwards = dlg.backwards;
    *whole_words = dlg.whole_words;
    *search_type = dlg.search_type;
    *all_charsets = dlg.all_charsets;
    let cpath = crate::terminal::viewer_ensure_view_for(path);
    let opts = viewer_search_opts(
        dlg.case_sensitive,
        dlg.backwards,
        dlg.whole_words,
        dlg.search_type,
        dlg.all_charsets,
    );
    match rmc_view::search_with_options(&cpath, *offset, &dlg.search, opts, true) {
        Ok(Some(pos)) => {
            *offset = pos;
            Ok(Some("Found".into()))
        }
        Ok(None) => Ok(Some("Not found".into())),
        Err(e) => {
            let msg = e.to_string();
            if msg.starts_with("Hex pattern error") {
                Ok(Some(msg))
            } else {
                Err(e)
            }
        }
    }
}

fn viewer_search_next(
    path: &std::path::Path,
    offset: &mut u64,
    needle: &str,
    opts: rmc_view::SearchOptions,
) -> anyhow::Result<Option<String>> {
    if needle.is_empty() {
        return Ok(None);
    }
    let cpath = crate::terminal::viewer_ensure_view_for(path);
    match rmc_view::search_next_with_options(&cpath, *offset, needle, opts, true)? {
        Some(pos) => {
            *offset = pos;
            Ok(Some("Found".into()))
        }
        None => Ok(Some("Not found".into())),
    }
}

/// Write the editor buffer to `path` and update `buf.path`. Errors are
/// returned as text for `status_msg` — never panic.
fn editor_save_to_path(
    vfs: &dyn rmc_fs::Vfs,
    buf: &mut rmc_edit::EditorBuffer,
    path: &std::path::Path,
) -> Result<(), String> {
    let mut w = vfs.write_file(path).map_err(|e| e.to_string())?;
    use std::io::Write;
    w.write_all(&buf.to_bytes()).map_err(|e| e.to_string())?;
    buf.path = Some(path.to_path_buf());
    buf.dirty = false;
    Ok(())
}

fn editor_ui_mode(buf: rmc_edit::EditorBuffer, return_to: Option<Box<UiMode>>) -> UiMode {
    UiMode::new_editor(buf, return_to)
}

/// GNU mc(1) Internal Diff Viewer: F4 edits the left file; F14 (Shift-F4) the right.
/// Returns `Some(true)` for the right pane, `Some(false)` for the left.
fn diff_edit_right_side(key: &KeyEvent) -> Option<bool> {
    match key.code {
        KeyCode::F(14) => Some(true),
        KeyCode::F(4) if key.modifiers.contains(KeyModifiers::SHIFT) => Some(true),
        KeyCode::F(4) if key.modifiers.is_empty() => Some(false),
        _ => None,
    }
}

fn read_vfs_bytes(app: &App, path: &std::path::Path) -> Vec<u8> {
    let mut data = Vec::new();
    if let Ok(mut r) = app.vfs.read_file(path) {
        use std::io::Read;
        let _ = r.read_to_end(&mut data);
    }
    data
}

fn read_vfs_text(app: &App, path: &std::path::Path) -> String {
    String::from_utf8_lossy(&read_vfs_bytes(app, path)).into_owned()
}

fn write_diff_file(app: &mut App, path: &std::path::Path, lines: &[String]) -> Result<()> {
    let mut w = app
        .vfs
        .write_file(path)
        .map_err(|e| anyhow::anyhow!(e.to_string()))?;
    use std::io::Write;
    let _ = w.write_all(rmc_diff::join_lines(lines).as_bytes());
    Ok(())
}

fn flush_diff_modified(app: &mut App, state: &mut rmc_core::app::DiffState) -> Result<()> {
    if state.left_modified {
        write_diff_file(app, &state.left_path, &state.left_lines)?;
        state.left_modified = false;
    }
    if state.right_modified {
        write_diff_file(app, &state.right_path, &state.right_lines)?;
        state.right_modified = false;
    }
    Ok(())
}

/// Re-read both sides from disk and rebuild hunks. Cursor hunk is clamped
/// unless `reset_cursor` (C-r style).
fn reload_diff_from_disk(app: &mut App, reset_cursor: bool) {
    let (left_path, right_path) = match &app.ui_mode {
        UiMode::Diff(s) => (s.left_path.clone(), s.right_path.clone()),
        _ => return,
    };
    let ltxt = read_vfs_text(app, &left_path);
    let rtxt = read_vfs_text(app, &right_path);
    let UiMode::Diff(state) = &mut app.ui_mode else {
        return;
    };
    state.left_lines = rmc_diff::split_lines(&ltxt);
    state.right_lines = rmc_diff::split_lines(&rtxt);
    state.hunks = rmc_diff::compute_diff(&ltxt, &rtxt).hunks;
    state.left_modified = false;
    state.right_modified = false;
    if reset_cursor {
        state.current_hunk = 0;
        state.left_scroll = 0;
        state.right_scroll = 0;
    } else if state.hunks.is_empty() {
        state.current_hunk = 0;
    } else {
        state.current_hunk = state.current_hunk.min(state.hunks.len() - 1);
        TerminalApp::ensure_hunk_visible(state);
    }
}

fn leave_editor(app: &mut App) {
    let prev = match &mut app.ui_mode {
        UiMode::Editor { return_to, .. } => return_to.take(),
        _ => None,
    };
    match prev {
        Some(boxed) => {
            app.ui_mode = *boxed;
            if matches!(app.ui_mode, UiMode::Diff(_)) {
                reload_diff_from_disk(app, false);
            }
        }
        None => close_current_screen_ui(app),
    }
}

fn close_current_screen_ui(app: &mut App) {
    if let UiMode::Viewer { path, .. } = &app.ui_mode {
        viewer_forget(path);
    }
    app.close_current_screen();
    if let UiMode::Viewer { path, .. } = &app.ui_mode {
        let p = path.clone();
        let _ = viewer_ensure_view_for(&p);
    }
}

fn push_internal_screen(app: &mut App, mode: UiMode) {
    if matches!(app.ui_mode, UiMode::Viewer { .. }) {
        park_current_viewer_to_cache();
    }
    app.push_screen(mode);
    if let UiMode::Viewer { path, .. } = &app.ui_mode {
        let p = path.clone();
        let _ = viewer_ensure_view_for(&p);
    }
}

fn switch_to_screen_ui(app: &mut App, idx: usize) {
    if matches!(app.ui_mode, UiMode::Viewer { .. }) {
        park_current_viewer_to_cache();
    }
    app.switch_screen(idx);
    if let UiMode::Viewer { path, .. } = &app.ui_mode {
        let p = path.clone();
        let _ = viewer_ensure_view_for(&p);
    }
}

fn cycle_screen_ui(app: &mut App, delta: isize) {
    if matches!(app.ui_mode, UiMode::Viewer { .. }) {
        park_current_viewer_to_cache();
    }
    app.cycle_screen(delta);
    if let UiMode::Viewer { path, .. } = &app.ui_mode {
        let p = path.clone();
        let _ = viewer_ensure_view_for(&p);
    }
}

fn screen_hotkeys_blocked(mode: &UiMode) -> bool {
    match mode {
        UiMode::Normal | UiMode::ShellInput => false,
        UiMode::Editor {
            show_menu,
            search_input,
            save_as_dialog,
            search_dialog,
            replace_dialog,
            pipe_dialog,
            goto_dialog,
            tab_spacing_dialog,
            confirm_exit,
            ..
        } => {
            show_menu.is_some()
                || search_input.is_some()
                || save_as_dialog.is_some()
                || search_dialog.is_some()
                || replace_dialog.is_some()
                || pipe_dialog.is_some()
                || goto_dialog.is_some()
                || tab_spacing_dialog.is_some()
                || confirm_exit.is_some()
        }
        UiMode::Viewer {
            viewer_menu,
            search_dialog,
            display_dialog,
            goto_prompt,
            search_prompt,
            ..
        } => {
            viewer_menu.is_some()
                || search_dialog.is_some()
                || display_dialog.is_some()
                || goto_prompt.is_some()
                || search_prompt.is_some()
        }
        UiMode::Diff(s) => {
            s.confirm_exit.is_some() || s.search_prompt.is_some() || s.goto_prompt.is_some()
        }
        _ => true,
    }
}

fn is_screen_cycle_key(key: &KeyEvent) -> Option<isize> {
    if !key.modifiers.contains(KeyModifiers::ALT) {
        return None;
    }
    match key.code {
        KeyCode::Char('}') | KeyCode::Char(']') => Some(1),
        KeyCode::Char('{') | KeyCode::Char('[') => Some(-1),
        _ => None,
    }
}

fn is_screen_list_key(key: &KeyEvent) -> bool {
    key.modifiers.contains(KeyModifiers::ALT) && matches!(key.code, KeyCode::Char('`'))
}

fn open_screen_list(app: &mut App) {
    let selected = app.screen_idx;
    let prev = std::mem::replace(&mut app.ui_mode, UiMode::Normal);
    let prev = match prev {
        UiMode::Menu { .. } => UiMode::Normal,
        other => other,
    };
    app.ui_mode = UiMode::ScreenList {
        selected,
        scroll_top: 0,
        focus: ScreenListFocus::List,
        prev: Box::new(prev),
    };
}

fn apply_screen_list_selection(app: &mut App, selected: usize, prev: Box<UiMode>) {
    app.ui_mode = *prev;
    switch_to_screen_ui(app, selected);
}

enum ScreenListAction {
    Stay,
    Cancel,
    Accept(usize),
}

fn screen_list_key_action(app: &mut App, key: &KeyEvent, page_rows: usize) -> ScreenListAction {
    use ScreenListFocus as F;
    let n = app.screens.len() + 1;
    let list_rows = page_rows.max(1);
    let UiMode::ScreenList {
        selected,
        scroll_top,
        focus,
        ..
    } = &mut app.ui_mode
    else {
        return ScreenListAction::Stay;
    };
    match key.code {
        KeyCode::Esc | KeyCode::F(10) => ScreenListAction::Cancel,
        KeyCode::Tab => {
            *focus = match *focus {
                F::List => F::Ok,
                F::Ok => F::Cancel,
                F::Cancel => F::List,
            };
            ScreenListAction::Stay
        }
        KeyCode::BackTab => {
            *focus = match *focus {
                F::List => F::Cancel,
                F::Ok => F::List,
                F::Cancel => F::Ok,
            };
            ScreenListAction::Stay
        }
        KeyCode::Left | KeyCode::Right if matches!(*focus, F::Ok | F::Cancel) => {
            *focus = if matches!(*focus, F::Ok) {
                F::Cancel
            } else {
                F::Ok
            };
            ScreenListAction::Stay
        }
        KeyCode::Up if matches!(*focus, F::List) => {
            if *selected > 0 {
                *selected -= 1;
            }
            if *selected < *scroll_top {
                *scroll_top = *selected;
            }
            ScreenListAction::Stay
        }
        KeyCode::Down if matches!(*focus, F::List) => {
            if n > 0 && *selected + 1 < n {
                *selected += 1;
            }
            if *selected >= *scroll_top + list_rows {
                *scroll_top = selected.saturating_sub(list_rows.saturating_sub(1));
            }
            ScreenListAction::Stay
        }
        KeyCode::Home if matches!(*focus, F::List) => {
            *selected = 0;
            *scroll_top = 0;
            ScreenListAction::Stay
        }
        KeyCode::End if matches!(*focus, F::List) => {
            if n > 0 {
                *selected = n - 1;
                *scroll_top = selected.saturating_sub(list_rows.saturating_sub(1));
            }
            ScreenListAction::Stay
        }
        KeyCode::Enter => match *focus {
            F::List | F::Ok => ScreenListAction::Accept(*selected),
            F::Cancel => ScreenListAction::Cancel,
        },
        _ => ScreenListAction::Stay,
    }
}

/// `mcr -e` / `--edit`: each path is an editor screen. Empty list → one untitled buffer.
pub fn open_editor_files(app: &mut App, paths: &[PathBuf]) {
    if paths.is_empty() {
        let buf = rmc_edit::EditorBuffer::from_bytes(b"", None);
        push_internal_screen(app, editor_ui_mode(buf, None));
        return;
    }
    for path in paths {
        let data = read_vfs_bytes(app, path);
        let buf = rmc_edit::EditorBuffer::from_bytes(&data, Some(path.clone()));
        push_internal_screen(app, editor_ui_mode(buf, None));
    }
}

/// GNU Command menu “Edit extension file” / “Edit menu file”: internal editor
/// on the user config path. Missing files open an empty buffer at that path.
fn open_user_config_in_editor(app: &mut App, path: PathBuf) {
    if let Some(parent) = path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let data = std::fs::read(&path).unwrap_or_default();
    let buf = rmc_edit::EditorBuffer::from_bytes(&data, Some(path));
    // Leave the pull-down so push_screen does not park Menu as a module.
    app.ui_mode = UiMode::Normal;
    push_internal_screen(app, editor_ui_mode(buf, None));
}

/// GNU mc(1) startup flags. Unknown args are skipped so they do not hide
/// `--diff` / `--edit` / `--view` later on the line.
///
/// `-U`/`--subshell` and `-u`/`--nosubshell` are mutually exclusive; last one
/// wins. `--skin` overrides `MC_SKIN` and the ini/default name for this process;
/// a missing named skin keeps that name and falls back visually the same way
/// Options → Appearance does (default palette).
///
/// Non-option operands are GNU panel directories: `mc [options] [dir1 [dir2]]`.
/// `dir1` opens on the current (active) panel; `dir2` opens on the other panel.
/// With the default left-current panel that is left then right. A lone `dir1`
/// changes only the current panel. Extra operands after the first two are
/// ignored. A directory that cannot be listed leaves that panel unchanged.
pub fn apply_cli_args(app: &mut App, args: &[String]) -> Result<()> {
    let mut i = 0;
    let mut positionals = Vec::new();
    while i < args.len() {
        let a = args[i].as_str();
        if a == "--" {
            positionals.extend_from_slice(&args[i + 1..]);
            break;
        }
        if let Some(long) = a.strip_prefix("--") {
            i = apply_long_option(app, long, args, i);
            continue;
        }
        if a.starts_with('-') && a != "-" {
            i = apply_short_cluster(app, a, args, i);
            continue;
        }
        positionals.push(a.to_string());
        i += 1;
    }
    apply_positional_panel_dirs(app, &positionals);
    Ok(())
}

/// GNU mc(1) 4.8.33: first operand → current panel; second → the other panel.
fn apply_positional_panel_dirs(app: &mut App, positionals: &[String]) {
    if positionals.is_empty() {
        return;
    }
    let first = resolve_cli_panel_dir(Path::new(&positionals[0]));
    let current = app.active;
    let _ = app.change_dir_on(current, &first);
    if let Some(second) = positionals.get(1) {
        let second = resolve_cli_panel_dir(Path::new(second));
        let other = match current {
            PaneSide::Left => PaneSide::Right,
            PaneSide::Right => PaneSide::Left,
        };
        let _ = app.change_dir_on(other, &second);
    }
}

/// Local relative operands are resolved against the process cwd. Remote/VFS
/// strings (`ftp://…`, `/#ftp:…`) are left as given so `change_dir` can enter.
fn resolve_cli_panel_dir(raw: &Path) -> PathBuf {
    if raw.is_absolute() {
        return raw.to_path_buf();
    }
    let s = raw.to_string_lossy();
    if s.contains("://") || s.contains('#') {
        return raw.to_path_buf();
    }
    match std::env::current_dir() {
        Ok(cwd) => cwd.join(raw),
        Err(_) => raw.to_path_buf(),
    }
}

/// GNU mc(1): `MC_SKIN` selects the skin after user ini and before `-S`/`--skin`.
/// Empty or unset values leave `app.skin_name` unchanged (ini / default).
pub fn apply_mc_skin_env(app: &mut App) {
    if let Some(name) = crate::skin::mc_skin_env_name() {
        app.skin_name = name;
    }
}

fn is_cli_option(s: &str) -> bool {
    s.starts_with('-') && s != "-"
}

fn take_non_option_files(args: &[String], start: usize) -> (Vec<PathBuf>, usize) {
    let mut files = Vec::new();
    let mut i = start;
    while i < args.len() && !is_cli_option(&args[i]) {
        files.push(PathBuf::from(&args[i]));
        i += 1;
    }
    (files, i)
}

fn apply_long_option(app: &mut App, long: &str, args: &[String], i: usize) -> usize {
    if let Some((key, val)) = long.split_once('=') {
        match key {
            "skin" => {
                app.skin_name = val.to_string();
                i + 1
            }
            "view" => {
                open_cli_viewer(app, PathBuf::from(val));
                i + 1
            }
            "edit" => {
                let mut files = vec![PathBuf::from(val)];
                let (more, next) = take_non_option_files(args, i + 1);
                files.extend(more);
                open_editor_files(app, &files);
                next
            }
            _ => i + 1,
        }
    } else {
        match long {
            "nomouse" => {
                app.mouse_enabled = false;
                i + 1
            }
            "nosubshell" => {
                app.use_subshell = false;
                i + 1
            }
            "subshell" => {
                app.use_subshell = true;
                i + 1
            }
            "skin" => {
                if i + 1 < args.len() {
                    app.skin_name = args[i + 1].clone();
                    i + 2
                } else {
                    i + 1
                }
            }
            "view" => {
                if i + 1 < args.len() {
                    open_cli_viewer(app, PathBuf::from(&args[i + 1]));
                    i + 2
                } else {
                    i + 1
                }
            }
            "edit" => {
                let (files, next) = take_non_option_files(args, i + 1);
                open_editor_files(app, &files);
                next
            }
            "diff" => {
                if i + 2 < args.len() {
                    open_cli_diff(
                        app,
                        PathBuf::from(&args[i + 1]),
                        PathBuf::from(&args[i + 2]),
                    );
                    i + 3
                } else {
                    i + 1
                }
            }
            _ => i + 1,
        }
    }
}

fn apply_short_cluster(app: &mut App, arg: &str, args: &[String], i: usize) -> usize {
    let chars: Vec<char> = arg[1..].chars().collect();
    let mut cidx = 0;
    while cidx < chars.len() {
        match chars[cidx] {
            'd' => app.mouse_enabled = false,
            'u' => app.use_subshell = false,
            'U' => app.use_subshell = true,
            'S' => {
                let rest: String = chars[cidx + 1..].iter().collect();
                if rest.is_empty() {
                    if i + 1 < args.len() {
                        app.skin_name = args[i + 1].clone();
                        return i + 2;
                    }
                    return i + 1;
                }
                app.skin_name = rest;
                return i + 1;
            }
            'v' => {
                let rest: String = chars[cidx + 1..].iter().collect();
                if rest.is_empty() {
                    if i + 1 < args.len() {
                        open_cli_viewer(app, PathBuf::from(&args[i + 1]));
                        return i + 2;
                    }
                    return i + 1;
                }
                open_cli_viewer(app, PathBuf::from(rest));
                return i + 1;
            }
            'e' => {
                let rest: String = chars[cidx + 1..].iter().collect();
                let mut files = Vec::new();
                if !rest.is_empty() {
                    files.push(PathBuf::from(rest));
                }
                let (more, next) = take_non_option_files(args, i + 1);
                files.extend(more);
                open_editor_files(app, &files);
                return next;
            }
            _ => {}
        }
        cidx += 1;
    }
    i + 1
}

fn open_cli_viewer(app: &mut App, path: PathBuf) {
    // GNU `-v`/`--view` always starts the internal viewer (mcview), not $PAGER.
    push_internal_screen(app, UiMode::new_viewer(path));
}

fn open_cli_diff(app: &mut App, left: PathBuf, right: PathBuf) {
    let ltxt = read_vfs_text(app, &left);
    let rtxt = read_vfs_text(app, &right);
    let left_lines = rmc_diff::split_lines(&ltxt);
    let right_lines = rmc_diff::split_lines(&rtxt);
    let dr = rmc_diff::compute_diff(&ltxt, &rtxt);
    app.push_screen(UiMode::Diff(rmc_core::app::DiffState {
        left_path: left,
        right_path: right,
        left_lines,
        right_lines,
        hunks: dr.hunks,
        current_hunk: 0,
        left_modified: false,
        right_modified: false,
        show_line_numbers: false,
        show_hunk_status: true,
        search: None,
        search_prompt: None,
        goto_prompt: None,
        confirm_exit: None,
        left_scroll: 0,
        right_scroll: 0,
        panel_ratio: 0.5,
        tab_width: 4,
        merge_target_right: true,
    }));
}

fn open_diff_side_in_editor(app: &mut App, right: bool) -> Result<()> {
    let UiMode::Diff(mut state) = std::mem::replace(&mut app.ui_mode, UiMode::Normal) else {
        return Ok(());
    };
    if let Err(e) = flush_diff_modified(app, &mut state) {
        app.ui_mode = UiMode::Diff(state);
        return Err(e);
    }
    let path = if right {
        state.right_path.clone()
    } else {
        state.left_path.clone()
    };
    let data = read_vfs_bytes(app, &path);
    let buf = rmc_edit::EditorBuffer::from_bytes(&data, Some(path));
    app.ui_mode = editor_ui_mode(buf, Some(Box::new(UiMode::Diff(state))));
    Ok(())
}

/// GNU mcedit Save as is F12 (and Shift-F2, which terminals often send as F12).
fn is_editor_save_as_key(key: &KeyEvent) -> bool {
    matches!(key.code, KeyCode::F(12))
        || (matches!(key.code, KeyCode::F(2)) && key.modifiers.contains(KeyModifiers::SHIFT))
}

/// Open the Save as dialog, clearing other editor overlays. No-op if already open.
#[allow(clippy::too_many_arguments)]
fn editor_open_save_as_dialog(
    buf: &rmc_edit::EditorBuffer,
    search_input: &mut Option<String>,
    save_as_dialog: &mut Option<Box<EditorSaveAsDialog>>,
    search_dialog: &mut Option<Box<EditorSearchDialog>>,
    replace_dialog: &mut Option<Box<EditorReplaceDialog>>,
    pipe_dialog: &mut Option<EditorPipeDialog>,
    goto_dialog: &mut Option<Box<EditorGotoDialog>>,
    tab_spacing_dialog: &mut Option<Box<EditorTabSpacingDialog>>,
    status_msg: &mut Option<String>,
    show_menu: &mut Option<EditorMenu>,
) {
    if save_as_dialog.is_some() {
        return;
    }
    *search_input = None;
    *search_dialog = None;
    *replace_dialog = None;
    *pipe_dialog = None;
    *goto_dialog = None;
    *tab_spacing_dialog = None;
    *status_msg = None;
    *show_menu = None;
    *save_as_dialog = Some(Box::new(EditorSaveAsDialog::from_buffer_path(
        buf.path.as_deref(),
    )));
}

/// Commit Save as OK. Empty path: no-op close. Existing dest: GNU overwrite
/// confirm when `confirm_overwrite` is on (unless dest is the current path).
/// Write errors leave the dialog open with an error status (never panic).
/// Returns true when the dialog should close.
fn editor_save_as_commit(
    vfs: &dyn rmc_fs::Vfs,
    confirm_overwrite: bool,
    buf: &mut rmc_edit::EditorBuffer,
    dlg: &mut EditorSaveAsDialog,
    status_msg: &mut Option<String>,
) -> bool {
    let dest = dlg.filename.trim();
    if dest.is_empty() {
        return true;
    }
    let path = std::path::PathBuf::from(dest);
    let same_as_current = buf.path.as_deref() == Some(path.as_path());
    if !same_as_current {
        match vfs.stat(&path) {
            Ok(meta) if meta.is_dir => {
                *status_msg = Some("Cannot save: destination is not a regular file".into());
                return false;
            }
            Ok(_) if confirm_overwrite => {
                dlg.overwrite = Some(rmc_core::app::YncDialog {
                    title: "Warning".into(),
                    message: "A file already exists with this name".into(),
                    focus: rmc_core::app::YncFocus::Yes,
                });
                return false;
            }
            Ok(_) | Err(_) => {}
        }
    }
    match editor_save_to_path(vfs, buf, &path) {
        Ok(()) => {
            *status_msg = Some("Saved".into());
            true
        }
        Err(e) => {
            *status_msg = Some(e);
            false
        }
    }
}

/// Apply Options → Tab spacing. Empty or non-numeric is a no-op; values
/// outside 2–16 are clamped (mcedit(1) default 8; range from the dialog).
fn editor_tab_spacing_apply(buf: &mut rmc_edit::EditorBuffer, width: &str) {
    let t = width.trim();
    if t.is_empty() {
        return;
    }
    let Ok(n) = t.parse::<i64>() else {
        return;
    };
    let n = n.clamp(
        rmc_edit::MIN_TAB_WIDTH as i64,
        rmc_edit::MAX_TAB_WIDTH as i64,
    ) as usize;
    buf.set_tab_width(n);
}

/// Apply a 1-based decimal line number. Empty or non-numeric is a no-op.
/// `0` and negatives clamp to line 1; past-EOF is clamped by `goto_line`.
fn editor_goto_apply(buf: &mut rmc_edit::EditorBuffer, line: &str) {
    let t = line.trim();
    if t.is_empty() {
        return;
    }
    let Ok(n) = t.parse::<i64>() else {
        return;
    };
    if n <= 0 {
        buf.goto_line(1);
    } else if let Ok(n) = usize::try_from(n) {
        buf.goto_line(n);
    } else {
        buf.goto_line(usize::MAX);
    }
}

// Encode key events into bytes suitable for a typical xterm-compatible PTY.
fn encode_key_for_pty(key: &KeyEvent) -> Option<Vec<u8>> {
    use crossterm::event::{KeyCode, KeyModifiers};
    match key.code {
        KeyCode::Enter => Some(vec![b'\r']),
        KeyCode::Backspace => Some(vec![0x7f]),
        KeyCode::Tab => Some(vec![b'\t']),
        KeyCode::Esc => Some(vec![0x1b]),
        KeyCode::Left => Some(b"\x1b[D".to_vec()),
        KeyCode::Right => Some(b"\x1b[C".to_vec()),
        KeyCode::Up => Some(b"\x1b[A".to_vec()),
        KeyCode::Down => Some(b"\x1b[B".to_vec()),
        KeyCode::Home => Some(b"\x1b[H".to_vec()),
        KeyCode::End => Some(b"\x1b[F".to_vec()),
        KeyCode::Delete => Some(b"\x1b[3~".to_vec()),
        KeyCode::Insert => Some(b"\x1b[2~".to_vec()),
        KeyCode::PageUp => Some(b"\x1b[5~".to_vec()),
        KeyCode::PageDown => Some(b"\x1b[6~".to_vec()),
        KeyCode::Char(c) => {
            // Control-modified ASCII letters: map to ^A..^Z
            if key.modifiers.contains(KeyModifiers::CONTROL) {
                let uc = c.to_ascii_uppercase() as u8;
                if (b'@'..=b'_').contains(&uc) || uc.is_ascii_uppercase() {
                    // Common terminals map Ctrl-@..Ctrl-_ to 0x00..0x1f
                    let b = uc & 0x1f;
                    return Some(vec![b]);
                }
            }
            // Alt-modified: send ESC prefix + char
            if key.modifiers.contains(KeyModifiers::ALT) {
                let mut v = vec![0x1b];
                v.extend(c.to_string().as_bytes());
                return Some(v);
            }
            // Plain Unicode char => UTF-8 bytes
            Some(c.to_string().into_bytes())
        }
        _ => None,
    }
}

pub(crate) fn viewer_clear_state() {
    park_current_viewer_to_cache();
}

fn park_current_viewer_to_cache() {
    let mut cur = VIEWER_STATE.lock().expect("viewer state mutex poisoned");
    let mut cache = VIEWER_CACHE.lock().expect("viewer cache mutex poisoned");
    if let Some(s) = cur.take() {
        cache.insert(s.display_path.clone(), s);
    }
}

fn viewer_forget(path: &Path) {
    {
        let mut cur = VIEWER_STATE.lock().expect("viewer state mutex poisoned");
        if cur.as_ref().is_some_and(|s| s.display_path == path) {
            cur.take();
        }
    }
    if let Ok(mut cache) = VIEWER_CACHE.lock() {
        cache.remove(path);
    }
}

pub(crate) fn viewer_ensure_view_for(display_path: &std::path::Path) -> std::path::PathBuf {
    {
        let g = VIEWER_STATE.lock().expect("viewer state mutex poisoned");
        if let Some(s) = g.as_ref() {
            if s.display_path == display_path {
                return s.view.path().to_path_buf();
            }
        }
    }
    park_current_viewer_to_cache();
    {
        let mut cache = VIEWER_CACHE.lock().expect("viewer cache mutex poisoned");
        if let Some(s) = cache.remove(display_path) {
            let p = s.view.path().to_path_buf();
            let mut g = VIEWER_STATE.lock().expect("viewer state mutex poisoned");
            *g = Some(s);
            return p;
        }
    }
    let mut g = VIEWER_STATE.lock().expect("viewer state mutex poisoned");
    let need_new = g
        .as_ref()
        .map(|s| s.display_path != display_path)
        .unwrap_or(true);
    if need_new {
        match rmc_view::ViewData::open_view(display_path) {
            Ok(view) => {
                let p = view.path().to_path_buf();
                *g = Some(ViewerState {
                    display_path: display_path.to_path_buf(),
                    view,
                });
                return p;
            }
            Err(_) => {
                // Filter failed: never stash compressed bytes as if they were text.
                // view_current_file refuses to enter Viewer in this case.
                if rmc_view::guess_filter_for_path(display_path).is_none() {
                    let view = rmc_view::ViewData::from_path(display_path.to_path_buf());
                    let p = view.path().to_path_buf();
                    *g = Some(ViewerState {
                        display_path: display_path.to_path_buf(),
                        view,
                    });
                    return p;
                }
                return display_path.to_path_buf();
            }
        }
    }
    g.as_ref()
        .map(|s| s.view.path().to_path_buf())
        .unwrap_or_else(|| display_path.to_path_buf())
}

pub(crate) fn viewer_apply_filter_to_current(cmd: &str) -> anyhow::Result<()> {
    let mut g = VIEWER_STATE.lock().expect("viewer state mutex poisoned");
    if let Some(state) = g.as_mut() {
        let filter = rmc_view::ExternalFilter::new("sh")
            .with_args(["-c".to_string(), cmd.to_string()])
            .with_input(rmc_view::FilterInput::Stdin);
        let new_view = rmc_view::ViewData::from_filter(state.view.path(), &filter)?;
        state.view = new_view;
        Ok(())
    } else {
        anyhow::bail!("No active viewer");
    }
}

/// Reload viewer bytes as GNU Raw (on-disk) or Parsed (`mc.ext` `[view]` filter).
pub(crate) fn viewer_reload_parsed(
    display_path: &std::path::Path,
    parsed: bool,
) -> anyhow::Result<()> {
    let view = if parsed {
        rmc_view::ViewData::open_view(display_path)?
    } else {
        rmc_view::ViewData::from_path(display_path.to_path_buf())
    };
    let mut g = VIEWER_STATE.lock().expect("viewer state mutex poisoned");
    *g = Some(ViewerState {
        display_path: display_path.to_path_buf(),
        view,
    });
    Ok(())
}

fn viewer_term_size(page_rows: usize) -> (u16, u16) {
    crossterm::terminal::size().unwrap_or((80, page_rows.max(1) as u16 + 3))
}

fn viewer_page_down(
    path: &std::path::Path,
    hex: bool,
    wrap: bool,
    offset: u64,
    page_rows: usize,
) -> anyhow::Result<u64> {
    let (cols, rows) = viewer_term_size(page_rows);
    let content_rows = rows.saturating_sub(3);
    if hex {
        Ok(offset.saturating_add(16u64 * (content_rows as u64)))
    } else {
        let cpath = crate::terminal::viewer_ensure_view_for(path);
        Ok(rmc_view::nav_page_down(
            &cpath,
            offset,
            cols.saturating_sub(2),
            content_rows,
            wrap,
        )?)
    }
}

fn viewer_page_up(
    path: &std::path::Path,
    hex: bool,
    wrap: bool,
    offset: u64,
    page_rows: usize,
) -> anyhow::Result<u64> {
    let (cols, rows) = viewer_term_size(page_rows);
    let content_rows = rows.saturating_sub(3);
    if hex {
        Ok(offset.saturating_sub(16u64 * (content_rows as u64)))
    } else {
        let cpath = crate::terminal::viewer_ensure_view_for(path);
        Ok(rmc_view::nav_page_up(
            &cpath,
            offset,
            cols.saturating_sub(2),
            content_rows,
            wrap,
        )?)
    }
}

fn viewer_goto_end(
    path: &std::path::Path,
    hex: bool,
    wrap: bool,
    page_rows: usize,
) -> anyhow::Result<u64> {
    let (cols, rows) = viewer_term_size(page_rows);
    let content_rows = rows.saturating_sub(3);
    let cpath = crate::terminal::viewer_ensure_view_for(path);
    if hex {
        let len = rmc_view::file_len(&cpath)?;
        Ok(len.saturating_sub(16u64 * (content_rows as u64)))
    } else {
        Ok(rmc_view::nav_end(
            &cpath,
            cols.saturating_sub(2),
            content_rows,
            wrap,
        )?)
    }
}

fn viewer_line_down(path: &std::path::Path, hex: bool, offset: u64) -> anyhow::Result<u64> {
    if hex {
        Ok(offset.saturating_add(16))
    } else {
        let cpath = crate::terminal::viewer_ensure_view_for(path);
        Ok(rmc_view::nav_line_down(&cpath, offset)?)
    }
}

fn viewer_line_up(path: &std::path::Path, hex: bool, offset: u64) -> anyhow::Result<u64> {
    if hex {
        Ok(offset.saturating_sub(16))
    } else {
        let cpath = crate::terminal::viewer_ensure_view_for(path);
        Ok(rmc_view::nav_line_up(&cpath, offset)?)
    }
}

fn viewer_sel_clear(anchor: &mut Option<u64>) {
    *anchor = None;
}

fn viewer_sel_extend(anchor: &mut Option<u64>, cursor: u64) {
    if anchor.is_none() {
        *anchor = Some(cursor);
    }
}

fn viewer_open_search_dialog(app: &mut App, backwards: bool) {
    if let UiMode::Viewer {
        search,
        search_dialog,
        search_prompt,
        goto_prompt,
        status_msg,
        viewer_menu,
        ..
    } = &mut app.ui_mode
    {
        *search_prompt = None;
        *goto_prompt = None;
        *status_msg = None;
        *viewer_menu = None;
        let mut dlg =
            ViewerSearchDialog::from_last_search(search.as_deref().unwrap_or("").as_bytes());
        dlg.backwards = backwards;
        *search_dialog = Some(Box::new(dlg));
    }
}

fn viewer_open_display_options(app: &mut App) {
    if let UiMode::Viewer {
        hex,
        wrap,
        show_line_numbers,
        show_cr,
        search_dialog: None,
        display_dialog,
        search_prompt,
        goto_prompt,
        viewer_menu,
        ..
    } = &mut app.ui_mode
    {
        let ln = *show_line_numbers;
        let cr = *show_cr;
        let wrap = *wrap;
        let hex = *hex;
        *search_prompt = None;
        *goto_prompt = None;
        *viewer_menu = None;
        *display_dialog = Some(Box::new(ViewerDisplayDialog::from_viewer(
            ln, cr, wrap, hex,
        )));
    }
}

fn viewer_move_vertical(app: &mut App, dir: i8, extend: bool) -> anyhow::Result<()> {
    if let UiMode::Viewer {
        path,
        hex,
        offset,
        sel_anchor,
        sel_cursor,
        ..
    } = &mut app.ui_mode
    {
        let from = *sel_cursor;
        if extend {
            viewer_sel_extend(sel_anchor, from);
        } else {
            viewer_sel_clear(sel_anchor);
        }
        let next = if dir < 0 {
            viewer_line_up(path, *hex, from)?
        } else {
            viewer_line_down(path, *hex, from)?
        };
        *sel_cursor = next;
        *offset = next;
    }
    Ok(())
}

fn viewer_move_horizontal(app: &mut App, dir: i8, extend: bool) -> anyhow::Result<()> {
    if let UiMode::Viewer {
        sel_anchor,
        sel_cursor,
        ..
    } = &mut app.ui_mode
    {
        let from = *sel_cursor;
        if extend {
            viewer_sel_extend(sel_anchor, from);
        } else {
            viewer_sel_clear(sel_anchor);
        }
        *sel_cursor = if dir < 0 {
            from.saturating_sub(1)
        } else {
            from.saturating_add(1)
        };
    }
    Ok(())
}

fn viewer_move_page(
    app: &mut App,
    down: bool,
    page_rows: usize,
    extend: bool,
) -> anyhow::Result<()> {
    if let UiMode::Viewer {
        path,
        hex,
        wrap,
        offset,
        sel_anchor,
        sel_cursor,
        ..
    } = &mut app.ui_mode
    {
        let from = *offset;
        if extend {
            viewer_sel_extend(sel_anchor, from);
        } else {
            viewer_sel_clear(sel_anchor);
        }
        let next = if down {
            viewer_page_down(path, *hex, *wrap, from, page_rows)?
        } else {
            viewer_page_up(path, *hex, *wrap, from, page_rows)?
        };
        *offset = next;
        *sel_cursor = next;
    }
    Ok(())
}

fn viewer_move_home(app: &mut App, extend: bool) -> anyhow::Result<()> {
    if let UiMode::Viewer {
        offset,
        sel_anchor,
        sel_cursor,
        ..
    } = &mut app.ui_mode
    {
        if extend {
            viewer_sel_extend(sel_anchor, *sel_cursor);
        } else {
            viewer_sel_clear(sel_anchor);
        }
        *offset = rmc_view::nav_home();
        *sel_cursor = *offset;
    }
    Ok(())
}

fn viewer_move_end(app: &mut App, page_rows: usize, extend: bool) -> anyhow::Result<()> {
    if let UiMode::Viewer {
        path,
        hex,
        wrap,
        offset,
        sel_anchor,
        sel_cursor,
        ..
    } = &mut app.ui_mode
    {
        if extend {
            viewer_sel_extend(sel_anchor, *sel_cursor);
        } else {
            viewer_sel_clear(sel_anchor);
        }
        let next = viewer_goto_end(path, *hex, *wrap, page_rows)?;
        *offset = next;
        *sel_cursor = next;
    }
    Ok(())
}

