    #[test]
    fn f14_opens_new_empty_buffer_f4_edits_highlighted() {
        let root = temp_workspace();
        seed_listing(&root);
        let mut app = make_app(&root);
        goto_name(&mut app, "notes.txt");
        let highlighted = app
            .active_panel()
            .current_entry()
            .map(|e| e.path.clone())
            .unwrap();

        press(&mut app, KeyCode::F(4));
        let (path, _) = editor_path_and_empty(&app);
        assert_eq!(
            path.as_ref(),
            Some(&highlighted),
            "F4 edits the highlighted file"
        );
        press(&mut app, KeyCode::F(10));
        assert!(matches!(app.ui_mode, UiMode::Normal));

        press(&mut app, KeyCode::F(14));
        let (path, empty) = editor_path_and_empty(&app);
        assert!(
            path.as_ref().is_none_or(|p| p.as_os_str().is_empty()),
            "F14 must be a new/untitled buffer, got {path:?}"
        );
        assert!(empty, "F14 buffer must be empty");
        press(&mut app, KeyCode::F(10));

        press_rows(&mut app, KeyCode::F(4), KeyModifiers::SHIFT, 10);
        let (path, empty) = editor_path_and_empty(&app);
        assert!(
            path.as_ref().is_none_or(|p| p.as_os_str().is_empty()),
            "S-F4 must be a new/untitled buffer, got {path:?}"
        );
        assert!(empty);
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn f15_f16_dest_current_ignore_tags_f5_f6_other_and_tags() {
        let root = temp_workspace();
        let left = root.join("left");
        let right = root.join("right");
        std::fs::create_dir_all(&left).unwrap();
        std::fs::create_dir_all(&right).unwrap();
        std::fs::write(left.join("notes.txt"), b"hello\n").unwrap();
        std::fs::write(left.join("other.txt"), b"world\n").unwrap();
        let mut app = make_split_app(&left, &right);
        app.panel_opts.mark_moves_down = false;
        tag_name(&mut app, "other.txt");
        goto_name(&mut app, "notes.txt");

        press(&mut app, KeyCode::F(5));
        let (title, src, to) = copy_fields(&app);
        assert_eq!(title, "Copy");
        assert!(
            src.contains("other.txt"),
            "F5 must use tagged files, got {src:?}"
        );
        assert!(
            !src.contains("notes.txt"),
            "F5 tagged-only source must not add the untagged cursor, got {src:?}"
        );
        assert!(
            dest_in_dir(to, &right),
            "F5 dest defaults to the other panel, to={to} other={}",
            right.display()
        );
        assert!(
            !dest_in_dir(to, &left),
            "F5 dest must not default to the current panel, to={to} current={}",
            left.display()
        );
        press(&mut app, KeyCode::Esc);

        press(&mut app, KeyCode::F(15));
        let (title, src, to) = copy_fields(&app);
        assert_eq!(title, "Copy");
        assert_eq!(src, "notes.txt", "F15 ignores tags; selected file only");
        assert!(
            dest_in_dir(to, &left),
            "F15 dest defaults to the current panel, to={to} current={}",
            left.display()
        );
        assert!(
            !dest_in_dir(to, &right),
            "F15 dest must not default to the other panel, to={to} other={}",
            right.display()
        );
        press(&mut app, KeyCode::Esc);

        press_rows(&mut app, KeyCode::F(5), KeyModifiers::SHIFT, 10);
        let (title, src, to) = copy_fields(&app);
        assert_eq!(title, "Copy");
        assert_eq!(src, "notes.txt", "S-F5 == F15");
        assert!(dest_in_dir(to, &left), "S-F5 dest is current panel");
        press(&mut app, KeyCode::Esc);

        press(&mut app, KeyCode::F(6));
        let (title, src, to) = copy_fields(&app);
        assert_eq!(title, "Move");
        assert!(src.contains("other.txt"), "F6 uses tags, got {src:?}");
        assert!(dest_in_dir(to, &right), "F6 dest is other panel, to={to}");
        press(&mut app, KeyCode::Esc);

        press(&mut app, KeyCode::F(16));
        let (title, src, to) = copy_fields(&app);
        assert_eq!(title, "Move");
        assert_eq!(src, "notes.txt", "F16 ignores tags");
        assert!(dest_in_dir(to, &left), "F16 dest is current panel, to={to}");
        press(&mut app, KeyCode::Esc);

        press_rows(&mut app, KeyCode::F(6), KeyModifiers::SHIFT, 10);
        let (title, src, to) = copy_fields(&app);
        assert_eq!(title, "Move");
        assert_eq!(src, "notes.txt", "S-F6 == F16");
        assert!(dest_in_dir(to, &left));
        let _ = std::fs::remove_dir_all(&root);
    }

    fn delete_name(app: &App) -> &str {
        match &app.ui_mode {
            UiMode::DeleteDialog { name, .. } => name.as_str(),
            _ => panic!("expected DeleteDialog, got {}", mode_name(app)),
        }
    }

    #[test]
    fn f18_delete_single_ignores_tags_f8_uses_marks() {
        let root = temp_workspace();
        seed_listing(&root);
        let mut app = make_app(&root);
        app.panel_opts.mark_moves_down = false;
        tag_name(&mut app, "other.txt");
        goto_name(&mut app, "notes.txt");

        press(&mut app, KeyCode::F(8));
        assert_eq!(
            delete_name(&app),
            "other.txt",
            "F8 Delete uses tagged files, not the unmarked cursor"
        );
        press(&mut app, KeyCode::Esc);
        assert!(root.join("other.txt").exists());
        assert!(root.join("notes.txt").exists());

        press(&mut app, KeyCode::F(18));
        assert_eq!(
            delete_name(&app),
            "notes.txt",
            "F18 DeleteSingle is the cursor file even when marks exist"
        );
        press(&mut app, KeyCode::Char('y'));
        assert!(matches!(app.ui_mode, UiMode::Normal));
        assert!(
            !root.join("notes.txt").exists(),
            "F18 must delete the cursor file"
        );
        assert!(
            root.join("other.txt").exists(),
            "F18 must not delete tagged-but-not-cursor files"
        );

        std::fs::write(root.join("notes.txt"), b"hello\n").unwrap();
        app.reload_panels().unwrap();
        app.active_panel_mut().selection.clear();
        tag_name(&mut app, "other.txt");
        goto_name(&mut app, "notes.txt");
        press_rows(&mut app, KeyCode::F(8), KeyModifiers::SHIFT, 10);
        assert_eq!(delete_name(&app), "notes.txt", "S-F8 == F18");
        press(&mut app, KeyCode::Esc);

        app.active_panel_mut().selection.clear();
        tag_name(&mut app, "other.txt");
        tag_name(&mut app, "notes.txt");
        press(&mut app, KeyCode::F(8));
        assert_eq!(
            delete_name(&app),
            "2 files",
            "F8 with two marks is the GNU multi-select Delete dialog"
        );
        press(&mut app, KeyCode::Char('y'));
        assert!(!root.join("notes.txt").exists());
        assert!(!root.join("other.txt").exists());
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn f19_reopens_last_selected_pulldown_path() {
        let root = temp_workspace();
        seed_listing(&root);
        let mut app = make_app(&root);
        app.config_opts.drop_menus = false;
        goto_name(&mut app, "notes.txt");

        press(&mut app, KeyCode::F(19));
        match &app.ui_mode {
            UiMode::Menu {
                top_index,
                selected_index,
                dropped,
            } => {
                assert_eq!(*top_index, 0, "F19 with no history is F9 Left");
                assert_eq!(*selected_index, 0);
                assert!(!*dropped, "drop_menus off: bar only");
            }
            _ => panic!(
                "F19 with no history must open the menu, got {}",
                mode_name(&app)
            ),
        }
        press(&mut app, KeyCode::Esc);

        press(&mut app, KeyCode::F(9));
        press(&mut app, KeyCode::Right);
        press(&mut app, KeyCode::Down);
        press(&mut app, KeyCode::Down);
        press(&mut app, KeyCode::Down);
        press(&mut app, KeyCode::Down);
        match &app.ui_mode {
            UiMode::Menu {
                top_index,
                selected_index,
                dropped,
            } => {
                assert_eq!(*top_index, 1, "File menu");
                assert_eq!(*selected_index, 3, "Copy");
                assert!(*dropped);
            }
            _ => panic!("expected File→Copy, got {}", mode_name(&app)),
        }
        press(&mut app, KeyCode::Esc);
        assert!(matches!(app.ui_mode, UiMode::Normal));

        press(&mut app, KeyCode::F(19));
        match &app.ui_mode {
            UiMode::Menu {
                top_index,
                selected_index,
                dropped,
            } => {
                assert_eq!(*top_index, 1, "F19 reopens File");
                assert_eq!(*selected_index, 3, "F19 reopens Copy");
                assert!(*dropped, "F19 drops the last item path");
            }
            _ => panic!("F19 must reopen the pull-down, got {}", mode_name(&app)),
        }
        press(&mut app, KeyCode::Esc);

        press_rows(&mut app, KeyCode::F(9), KeyModifiers::SHIFT, 10);
        match &app.ui_mode {
            UiMode::Menu {
                top_index,
                selected_index,
                dropped,
            } => {
                assert_eq!(*top_index, 1, "S-F9 == F19");
                assert_eq!(*selected_index, 3);
                assert!(*dropped);
            }
            _ => panic!("S-F9 must be MenuLastSelected, got {}", mode_name(&app)),
        }
        let _ = std::fs::remove_dir_all(&root);
    }

