        let src = left.join("mode.bin");
        std::fs::write(&src, b"x").unwrap();
        std::fs::set_permissions(&src, std::fs::Permissions::from_mode(0o707)).unwrap();
        let mut app = make_split_app(&left, &right);
        goto_name(&mut app, "mode.bin");
