#[cfg(test)]
mod learn_keys_tests {
    use super::*;
    use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
    use rmc_core::config::KeyMap;
    use rmc_core::learn_keys::LearnKey;
    use rmc_fs::local::LocalFs;

    fn temp_workspace() -> std::path::PathBuf {
        let p = std::env::temp_dir().join(format!(
            "rmc-learn-keys-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir_all(&p).unwrap();
        p
    }

    fn make_app(cwd: &std::path::Path) -> App {
        let vfs = LocalFs::new();
        let mut app = App::new(Box::new(vfs), KeyMap::mc_defaults()).unwrap();
        app.change_dir(cwd).unwrap();
        app
    }

    fn press(app: &mut App, code: KeyCode) {
        TerminalApp::handle_key(app, KeyEvent::new(code, KeyModifiers::NONE), 10).unwrap();
    }

    fn press_ev(app: &mut App, ev: KeyEvent) {
        TerminalApp::handle_key(app, ev, 10).unwrap();
    }

    fn open_via_options_menu(app: &mut App) {
        app.config_opts.drop_menus = true;
        press(app, KeyCode::F(9));
        press(app, KeyCode::Right);
        press(app, KeyCode::Right);
        press(app, KeyCode::Right);
        for _ in 0..6 {
            press(app, KeyCode::Down);
        }
        press(app, KeyCode::Enter);
    }

    fn dialog_selected(app: &App) -> usize {
        match &app.ui_mode {
            UiMode::LearnKeysDialog { selected, .. } => *selected,
            _ => panic!("expected LearnKeysDialog"),
        }
    }

    fn f13_index() -> usize {
        rmc_core::learn_keys::LEARNABLE_KEYS
            .iter()
            .position(|k| *k == LearnKey::F(13))
            .expect("F13 is teachable")
    }

    #[test]
    fn options_menu_opens_learn_keys_dialog() {
        let root = temp_workspace();
        let mut app = make_app(&root);
        open_via_options_menu(&mut app);
        match &app.ui_mode {
            UiMode::LearnKeysDialog {
                keys,
                capturing,
                focus_save,
                ..
            } => {
                assert!(!*capturing);
                assert!(*focus_save);
                assert!(keys.iter().any(|r| r.key == LearnKey::F(1)));
                assert!(keys.iter().any(|r| r.key == LearnKey::Up));
                assert!(keys.iter().any(|r| r.key == LearnKey::Complete));
                assert!(keys.iter().any(|r| r.key == LearnKey::BackTab));
                assert_eq!(keys.len(), rmc_core::learn_keys::LEARNABLE_KEYS.len());
            }
            _ => panic!("Options → Learn keys must open the dialog"),
        }
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn first_f1_marks_ok_second_opens_help() {
        let root = temp_workspace();
        let mut app = make_app(&root);
        open_learn_keys_dialog(&mut app);
        press(&mut app, KeyCode::F(1));
        match &app.ui_mode {
            UiMode::LearnKeysDialog { keys, .. } => {
                let row = keys.iter().find(|r| r.key == LearnKey::F(1)).unwrap();
                assert!(row.ok, "first F1 only tests the key");
            }
            _ => panic!("still in Learn keys dialog after first F1"),
        }
        press(&mut app, KeyCode::F(1));
        assert!(
            matches!(app.ui_mode, UiMode::Help { .. }),
            "mc(1): after OK, F1 shows help"
        );
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn learned_f13_roundtrip_takes_effect_and_persists() {
        let root = temp_workspace();
        let cfg = root.join("cfg");
        std::fs::create_dir_all(&cfg).unwrap();
        let prev = std::env::var("MCR_CONFIG_DIR").ok();
        std::env::set_var("MCR_CONFIG_DIR", &cfg);

        let mut app = make_app(&root);
        app.learned_keys.term = "xterm-learn".into();
        open_learn_keys_dialog(&mut app);
        if let UiMode::LearnKeysDialog { selected, .. } = &mut app.ui_mode {
            *selected = f13_index();
        }
        press(&mut app, KeyCode::Enter);
        match &app.ui_mode {
            UiMode::LearnKeysDialog { capturing, .. } => {
                assert!(*capturing, "Enter on a key button asks to press that key");
            }
            _ => panic!("expected capture prompt"),
        }
        press(&mut app, KeyCode::F(15));
        match &app.ui_mode {
            UiMode::LearnKeysDialog {
                keys, capturing, ..
            } => {
                assert!(!*capturing);
                let row = keys.iter().find(|r| r.key == LearnKey::F(13)).unwrap();
                assert!(row.ok);
                assert!(row.captured.is_some());
            }
            _ => panic!("expected dialog after capture"),
        }
        if let UiMode::LearnKeysDialog { selected, .. } = &mut app.ui_mode {
            *selected = rmc_core::learn_keys::LEARNABLE_KEYS.len();
        }
        press(&mut app, KeyCode::Enter);
        assert!(
            matches!(app.ui_mode, UiMode::Normal),
            "Save closes the dialog"
        );
        let remapped = app
            .learned_keys
            .remap(KeyEvent::new(KeyCode::F(15), KeyModifiers::NONE));
        assert_eq!(remapped.code, KeyCode::F(13));

        let ini = std::fs::read_to_string(cfg.join("ini")).unwrap_or_default();
        assert!(
            ini.contains("[terminal:xterm-learn]"),
            "GNU-compatible [terminal:TERM] under config root, got {ini}"
        );
        assert!(ini.contains("f13="), "redefined F13 must be written: {ini}");

        let mut app2 = make_app(&root);
        app2.learned_keys = rmc_core::learn_keys::LearnedKeyStore::for_term("xterm-learn".into());
        rmc_core::config::load_user_setup_from(&mut app2, &cfg).unwrap();
        let got = app2
            .learned_keys
            .remap(KeyEvent::new(KeyCode::F(15), KeyModifiers::NONE));
        assert_eq!(got.code, KeyCode::F(13), "reload must restore the remap");

        match prev {
            Some(v) => std::env::set_var("MCR_CONFIG_DIR", v),
            None => std::env::remove_var("MCR_CONFIG_DIR"),
        }
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn tab_always_moves_and_esc_aborts_capture() {
        let root = temp_workspace();
        let mut app = make_app(&root);
        open_learn_keys_dialog(&mut app);
        assert_eq!(dialog_selected(&app), 0);
        press(&mut app, KeyCode::Tab);
        assert_eq!(dialog_selected(&app), 1);
        press(&mut app, KeyCode::Enter);
        press(&mut app, KeyCode::Esc);
        match &app.ui_mode {
            UiMode::LearnKeysDialog { capturing, .. } => {
                assert!(!*capturing, "Esc aborts the press-that-key box");
            }
            _ => panic!("Esc should abort capture and stay in the dialog"),
        }
        press(&mut app, KeyCode::Esc);
        assert!(matches!(app.ui_mode, UiMode::Normal));
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn keymap_c_backslash_unrelated_to_learn_keys() {
        let km = KeyMap::mc_defaults();
        assert!(matches!(
            km.resolve(&KeyEvent::new(KeyCode::Char('\\'), KeyModifiers::CONTROL)),
            Some(Action::OpenHotlist)
        ));
        let root = temp_workspace();
        let mut app = make_app(&root);
        open_learn_keys_dialog(&mut app);
        press(&mut app, KeyCode::Esc);
        press_ev(
            &mut app,
            KeyEvent::new(KeyCode::Char('\\'), KeyModifiers::CONTROL),
        );
        assert!(
            matches!(app.ui_mode, UiMode::HotlistDialog(_)),
            "C-\\\\ still opens the hotlist after Learn keys"
        );
        let _ = std::fs::remove_dir_all(&root);
    }
}

#[cfg(test)]
mod jobs_dialog_stop_restart_kill_tests {
    use super::*;
    use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
    use rmc_core::app::{App, JobsDialogFocus, UiMode};
    use rmc_core::config::KeyMap;
    use rmc_core::jobs::JobStatus;
    use rmc_fs::local::LocalFs;
    use rmc_fs::CopyFlags;
    use std::path::PathBuf;
    use std::time::{Duration, Instant};

    fn temp_workspace() -> PathBuf {
        let p = std::env::temp_dir().join(format!(
            "rmc-jobs-dialog-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir_all(&p).unwrap();
        p
    }

    fn make_app(cwd: &std::path::Path) -> App {
        let vfs = LocalFs::new();
        let mut app = App::new(Box::new(vfs), KeyMap::mc_defaults()).unwrap();
        app.change_dir(cwd).unwrap();
        app
    }

    fn press(app: &mut App, code: KeyCode) {
        TerminalApp::handle_key(app, KeyEvent::new(code, KeyModifiers::NONE), 10).unwrap();
    }

    fn press_ctrl(app: &mut App, c: char) {
        TerminalApp::handle_key(
            app,
            KeyEvent::new(KeyCode::Char(c), KeyModifiers::CONTROL),
            10,
        )
        .unwrap();
    }

    fn open_jobs_dialog(app: &mut App) {
        press_ctrl(app, 'x');
        press(app, KeyCode::Char('j'));
    }

    fn jobs_focus(app: &App) -> JobsDialogFocus {
        match &app.ui_mode {
            UiMode::JobsDialog { focus, .. } => *focus,
            _ => panic!("expected JobsDialog"),
        }
    }

    fn wait_status(app: &App, id: rmc_core::jobs::JobId, want: JobStatus, ms: u64) {
        let start = Instant::now();
        loop {
            if app.jobs.get(id).map(|j| j.status) == Some(want) {
                return;
            }
            if start.elapsed() > Duration::from_millis(ms) {
                panic!("job {id} did not reach {want:?}: {:?}", app.jobs.get(id));
            }
            std::thread::sleep(Duration::from_millis(5));
        }
    }

    #[test]
    fn ctrl_x_j_opens_jobs_dialog_on_list() {
        let root = temp_workspace();
        let mut app = make_app(&root);
        open_jobs_dialog(&mut app);
        assert!(matches!(
            app.ui_mode,
            UiMode::JobsDialog {
                selected_index: 0,
                focus: JobsDialogFocus::List,
            }
        ));
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn tab_cycles_stop_restart_kill_cleanup_ok() {
        let root = temp_workspace();
        let mut app = make_app(&root);
        open_jobs_dialog(&mut app);
        assert_eq!(jobs_focus(&app), JobsDialogFocus::List);
        press(&mut app, KeyCode::Tab);
        assert_eq!(jobs_focus(&app), JobsDialogFocus::Stop);
        press(&mut app, KeyCode::Tab);
        assert_eq!(jobs_focus(&app), JobsDialogFocus::Restart);
        press(&mut app, KeyCode::Tab);
        assert_eq!(jobs_focus(&app), JobsDialogFocus::Kill);
        press(&mut app, KeyCode::Tab);
        assert_eq!(jobs_focus(&app), JobsDialogFocus::Cleanup);
        press(&mut app, KeyCode::Tab);
        assert_eq!(jobs_focus(&app), JobsDialogFocus::Ok);
        press(&mut app, KeyCode::Tab);
        assert_eq!(jobs_focus(&app), JobsDialogFocus::List);
        press(&mut app, KeyCode::BackTab);
        assert_eq!(jobs_focus(&app), JobsDialogFocus::Ok);
        press(&mut app, KeyCode::Enter);
        assert!(matches!(app.ui_mode, UiMode::Normal));
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn stop_restart_enter_and_letter_keys() {
        let root = temp_workspace();
        let src = root.join("big.bin");
        let dst = root.join("out.bin");
        std::fs::write(&src, vec![0xABu8; 8 * 1024 * 1024]).unwrap();
        let mut app = make_app(&root);
        let id = app.jobs.spawn_copy_with_flags(
            &src,
            &dst,
            CopyFlags {
                use_cow_file_cloning: false,
                preallocate_space: false,
                ..CopyFlags::default()
            },
        );
        let start = Instant::now();
        loop {
            match app.jobs.get(id).map(|j| j.status) {
                Some(JobStatus::Running) if app.jobs.get(id).unwrap().bytes_done > 0 => break,
                Some(s) if s.is_finished() => {
                    panic!("copy finished before Stop could be tested: {s:?}");
                }
                _ => {}
            }
            if start.elapsed() > Duration::from_secs(5) {
                panic!("copy never advanced: {:?}", app.jobs.get(id));
            }
            std::thread::yield_now();
        }
        open_jobs_dialog(&mut app);
        press(&mut app, KeyCode::Tab); // Stop
        press(&mut app, KeyCode::Enter);
        wait_status(&app, id, JobStatus::Stopped, 5_000);

        press(&mut app, KeyCode::Tab); // Restart
        press(&mut app, KeyCode::Enter);
        let start = Instant::now();
        loop {
            match app.jobs.get(id).map(|j| j.status) {
                Some(JobStatus::Running | JobStatus::Done) => break,
                Some(JobStatus::Stopped) => {}
                other => panic!("unexpected after Restart: {other:?}"),
            }
            if start.elapsed() > Duration::from_secs(5) {
                panic!("Restart did not resume: {:?}", app.jobs.get(id));
            }
            std::thread::sleep(Duration::from_millis(5));
        }

        // Kill via GNU accelerator, whether still running or already done.
        press(&mut app, KeyCode::Char('k'));
        assert!(
            app.jobs.get(id).is_none(),
            "Kill letter-key must remove the job"
        );
        assert!(matches!(app.ui_mode, UiMode::JobsDialog { .. }));
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn kill_button_removes_and_cleanup_drops_finished() {
        let root = temp_workspace();
        let src = root.join("tiny.bin");
        let dst = root.join("tiny.out");
        std::fs::write(&src, b"hi").unwrap();
        let mut app = make_app(&root);
        let id = app.jobs.spawn_copy_with_flags(
            &src,
            &dst,
            CopyFlags {
                use_cow_file_cloning: false,
                ..CopyFlags::default()
            },
        );
        let start = Instant::now();
        loop {
            if app
                .jobs
                .get(id)
                .map(|j| j.status.is_finished())
                .unwrap_or(false)
            {
                break;
            }
            if start.elapsed() > Duration::from_secs(5) {
                panic!("tiny copy did not finish: {:?}", app.jobs.get(id));
            }
            std::thread::sleep(Duration::from_millis(5));
        }
        assert_eq!(app.jobs.get(id).unwrap().status, JobStatus::Done);
        open_jobs_dialog(&mut app);
        // List → Stop → Restart → Kill → Cleanup
        for _ in 0..4 {
            press(&mut app, KeyCode::Tab);
        }
        assert_eq!(jobs_focus(&app), JobsDialogFocus::Cleanup);
        press(&mut app, KeyCode::Enter);
        assert!(app.jobs.get(id).is_none(), "Clean up drops finished jobs");
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn gnu_button_labels_are_stop_restart_kill() {
        assert_eq!(
            rmc_core::app::JOBS_DIALOG_BUTTONS
                .iter()
                .map(|(_, s)| *s)
                .collect::<Vec<_>>(),
            vec!["Stop", "Restart", "Kill", "Clean up", "OK"]
        );
    }
}
